-- source: archived migration SQL
CREATE TABLE IF NOT EXISTS company_aliases (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  company_id    text NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
  alias_name    text NOT NULL,
  alias_type    text NOT NULL CHECK (alias_type IN (
                  'primary',       -- official legal name
                  'ticker',        -- stock ticker (ABBV, MRK, etc.)
                  'abbreviation',  -- common short form (J&J, BI, GSK)
                  'common',        -- informal / press name (AbbVie, Merck)
                  'subsidiary',    -- acquired or operating subsidiary (Genentech, Janssen)
                  'former'         -- historical name (Wyeth, Schering-Plough)
                )),
  source        text DEFAULT 'seed',   -- 'seed' | 'resolver' | 'manual'
  confidence    int  DEFAULT 100 CHECK (confidence BETWEEN 0 AND 100),
  is_primary    bool DEFAULT false,
  created_at    timestamptz DEFAULT now(),
  UNIQUE (company_id, alias_name)
);

-- source: archived migration SQL
CREATE OR REPLACE VIEW company_area_detail AS
  SELECT
    c.id            AS company_id,
    c.name,
    c.ticker,
    c.company_type,
    c.insight_text,
    c.ailux_angle,
    ca.area_id,
    cp.platform_summary,
    cp.bd_summary,
    cp.key_risk,
    cp.why_it_matters,
    cp.pipeline_url,
    cp.last_enriched_at,
    cp.enriched_by
  FROM companies c
  JOIN company_areas   ca ON ca.company_id = c.id
  LEFT JOIN company_profiles cp ON cp.company_id = c.id AND cp.area_id = ca.area_id;

