CREATE TABLE IF NOT EXISTS entity_consistency_checks (

  -- Identity
  id                    SERIAL PRIMARY KEY,

  -- Entity being checked
  entity_type           TEXT NOT NULL,
    -- 'drug' | 'indication' | 'target' | 'trial'
  entity_id             TEXT NOT NULL,
    -- drug_id, indication_id, target_id, trial_id, etc.
  issue_key             TEXT NOT NULL,
    -- Stable slug identifying this specific issue within the entity.
    -- Allows multiple issues with the same classification on one entity.
    -- Examples: legacy_ibd_noise | legacy_tl1a_noise |
    --           missing_ted_indication | missing_gmg_indication |
    --           mechanism_field_conflict | atopy_ad_gap

  -- Classification
  check_type            TEXT NOT NULL
    CHECK (check_type IN (
      'cross_table_inconsistency',
      'source_conflict',
      'ontology_scope_difference',
      'normalized_gap',
      'needs_manual_review'
    )),
    -- detection category: how the inconsistency was found
  classification        TEXT NOT NULL
    CHECK (classification IN (
      'legacy_noise_removed',
      'normalized_gap',
      'ontology_scope_difference',
      'needs_manual_review',
      'new_normalized_value',
      'source_conflict',
      'cross_table_inconsistency',
      'ibd_indication_not_tl1a_target'
    )),
    -- resolution label (Phase 4A/4B language)
    -- To extend: ALTER TABLE entity_consistency_checks
    --   DROP CONSTRAINT entity_consistency_checks_classification_check,
    --   ADD CONSTRAINT entity_consistency_checks_classification_check
    --   CHECK (classification IN (...existing..., 'new_value'));

-- source: archived migration SQL
CREATE TABLE IF NOT EXISTS entity_edges (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),

    -- Subject
    subject_type        TEXT NOT NULL CHECK (subject_type IN ('drug', 'company', 'target', 'area')),
    subject_id          TEXT NOT NULL,

    -- Predicate
    predicate           TEXT NOT NULL CHECK (predicate IN (
                            'COMPETES_WITH',
                            'SIMILAR_TO',
                            'DERIVED_FROM',
                            'TARGETS',
                            'ACTIVE_IN'
                        )),

    -- Object
    object_type         TEXT NOT NULL CHECK (object_type IN ('drug', 'company', 'target', 'area')),
    object_id           TEXT NOT NULL,

    -- Scope (optional — a COMPETES_WITH edge is scoped to an area)
    scope_area_id       TEXT,

    -- Provenance
    confidence_level    TEXT NOT NULL DEFAULT 'inferred'
                        CHECK (confidence_level IN ('confirmed', 'supported', 'inferred')),
    source_url          TEXT,
    generation_method   TEXT NOT NULL DEFAULT 'manual'
                        CHECK (generation_method IN ('deterministic', 'llm_assisted', 'manual')),

    -- Rationale (why was this edge created?)
    rationale           TEXT,

    -- Status
    status              TEXT NOT NULL DEFAULT 'active'
                        CHECK (status IN ('active', 'deprecated', 'disputed')),

    -- Audit
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by          TEXT NOT NULL DEFAULT 'system',
    notes               TEXT,

    -- Uniqueness: one edge per (subject, predicate, object, scope)
    CONSTRAINT uq_entity_edge UNIQUE (subject_type, subject_id, predicate, object_type, object_id, scope_area_id)
);

